window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-49f66202298a5bb6"]={"versions": [{"id": "FIG-49f66202298a5bb6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform Transportprotokolls nach SAE J1939 (<code>J1939Tp</code>). Das Diagramm illustriert das Zusammenspiel zwischen dem PDU-Router (<code>PduR</code>) und dem <code>J1939Tp</code>-Modul auf Sender- und Empfängerseite während einer verbindungsorientierten Datenübertragung mittels Connection Management (BAM/CM) unter Berücksichtigung von Übertragungsfehlern und Wiederholungsmechanismen (Retry Handling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> instanziiert bzw. adressiert):</p>\n<ul class=\"fig-list\">\n<li><code>PduR</code> (Senderseite, Caller)</li>\n<li><code>J1939Tp</code> (Senderseite, Transport Layer Modul)</li>\n<li><code>:J1939Tp</code> (Empfängerseite, korrespondierender Transport Layer Endpunkt)</li>\n<li><code>:PduR</code> (Empfängerseite, Callee / Data Sink)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li>Steuer- und Daten-APIs zwischen PduR und J1939Tp: <code>J1939Tp_Transmit()</code>, <code>PduR_J1939TpStartOfReception()</code>, <code>PduR_J1939TpCopyTxData()</code>, <code>PduR_J1939TpCopyRxData()</code>, <code>PduR_J1939TpRxIndication()</code>, <code>PduR_J1939TpTxConfirmation()</code></li>\n<li>SAE J1939 Protokollnachrichten (CAN-Bus-Ebene): <code>TP.CM_RTS()</code>, <code>TP.CM_CTS()</code>, <code>TP.DT()</code>, <code>TP.EOMACK()</code></li>\n<li>Zustandsvariablen / interne Parameter: <code>TpDataState</code> (<code>TP_DATACONF</code>, <code>TP_CONFPENDING</code>, <code>TP_DATARETRY</code>), <code>TxTpDataCnt</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Verbindungsaufbau:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> initiiert die Übertragung über <code>J1939Tp_Transmit()</code>.</li>\n<li>Sender-<code>J1939Tp</code> sendet die Verbindungsanforderung <code>TP.CM_RTS()</code> an <code>:J1939Tp</code>.</li>\n<li>Empfänger meldet den Beginn über <code>PduR_J1939TpStartOfReception()</code> an <code>:PduR</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Blockübertragung (<code>loop for Each Block</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger antwortet mit <code>TP.CM_CTS()</code> zur Freigabe eines Übertragungsblocks.</li>\n<li>Paketübertragung (<code>loop for Each Packet</code>):</li>\n<li>Sender fragt Nutzdaten über <code>PduR_J1939TpCopyTxData()</code> an. Dabei wird <code>TpDataState = TP_DATACONF</code> für das erste Paket des Blocks bzw. <code>TP_CONFPENDING</code> für Folgepakete gesetzt.</li>\n<li>Sender übermittelt das Datenpaket via <code>TP.DT()</code>.</li>\n<li>Verzweigung Fehlerfall (<code>alt TP.DT lost</code>):</li>\n<li><code>[NO]</code>: Paket kommt fehlerfrei an; Empfänger ruft <code>PduR_J1939TpCopyRxData()</code> auf.</li>\n<li><code>[YES]</code>: Paket geht verloren; Empfänger sendet erneutes <code>TP.CM_CTS()</code> (Anforderung ab Fehlpaket/Blockstart, Notiz: „Next Packet set to first Packet of Block“). Sender fordert über <code>PduR_J1939TpCopyTxData()</code> mit <code>TpDataState = TP_DATARETRY</code> und <code>TxTpDataCnt = Offset in bytes to start of Block</code> erneut Daten ab, sendet <code>TP.DT()</code> erneut und Empfänger reicht die Daten mittels <code>PduR_J1939TpCopyRxData()</code> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Übertragungsabschluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach vollständigem Empfang quittiert <code>:J1939Tp</code> mit <code>TP.EOMACK()</code> an <code>J1939Tp</code> und signalisiert den Abschluss über <code>PduR_J1939TpRxIndication()</code> an <code>:PduR</code>.</li>\n<li>Sender-<code>J1939Tp</code> bestätigt den Gesamtabschluss an <code>PduR</code> mittels <code>PduR_J1939TpTxConfirmation()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt das normative Retry-Verhalten für J1939Tp bei Paketverlust während blockweiser TP.DT-Übertragung. Implementierer müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Der Sender muss bei Retry (<code>TpDataState = TP_DATARETRY</code>) über <code>TxTpDataCnt</code> den Pufferzeiger im oberen Layer (<code>PduR</code>) exakt auf den Byte-Offset des Blockanfangs zurücksetzen können (Pufferverwaltung muss Rückspulen/Rewind unterstützen).</li>\n<li>Der Empfänger detektiert fehlende oder unvollständige Pakete innerhalb eines Blocks und steuert die Wiederholung über ein erneutes CTS mit dem entsprechenden Sequenznummernbezug aus.</li>\n<li>Quittierungszustände (<code>TP_DATACONF</code> vs. <code>TP_CONFPENDING</code>) definieren, ab wann vorherige Blockdaten durch die PDU-Router-Pufferverwaltung freigegeben werden dürfen.</li>\n</ul>"}, {"id": "FIG-d5705d4016da7b3c", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform Transportprotokolls nach SAE J1939 (<code>J1939Tp</code>). Das Diagramm illustriert das Zusammenspiel zwischen dem PDU-Router (<code>PduR</code>) und dem <code>J1939Tp</code>-Modul auf Sender- und Empfängerseite während einer verbindungsorientierten Datenübertragung mittels Connection Management (BAM/CM) unter Berücksichtigung von Übertragungsfehlern und Wiederholungsmechanismen (Retry Handling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> instanziiert bzw. adressiert):</p>\n<ul class=\"fig-list\">\n<li><code>PduR</code> (Senderseite, Caller)</li>\n<li><code>J1939Tp</code> (Senderseite, Transport Layer Modul)</li>\n<li><code>:J1939Tp</code> (Empfängerseite, korrespondierender Transport Layer Endpunkt)</li>\n<li><code>:PduR</code> (Empfängerseite, Callee / Data Sink)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li>Steuer- und Daten-APIs zwischen PduR und J1939Tp: <code>J1939Tp_Transmit()</code>, <code>PduR_J1939TpStartOfReception()</code>, <code>PduR_J1939TpCopyTxData()</code>, <code>PduR_J1939TpCopyRxData()</code>, <code>PduR_J1939TpRxIndication()</code>, <code>PduR_J1939TpTxConfirmation()</code></li>\n<li>SAE J1939 Protokollnachrichten (CAN-Bus-Ebene): <code>TP.CM_RTS()</code>, <code>TP.CM_CTS()</code>, <code>TP.DT()</code>, <code>TP.EOMACK()</code></li>\n<li>Zustandsvariablen / interne Parameter: <code>TpDataState</code> (<code>TP_DATACONF</code>, <code>TP_CONFPENDING</code>, <code>TP_DATARETRY</code>), <code>TxTpDataCnt</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Verbindungsaufbau:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> initiiert die Übertragung über <code>J1939Tp_Transmit()</code>.</li>\n<li>Sender-<code>J1939Tp</code> sendet die Verbindungsanforderung <code>TP.CM_RTS()</code> an <code>:J1939Tp</code>.</li>\n<li>Empfänger meldet den Beginn über <code>PduR_J1939TpStartOfReception()</code> an <code>:PduR</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Blockübertragung (<code>loop for Each Block</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger antwortet mit <code>TP.CM_CTS()</code> zur Freigabe eines Übertragungsblocks.</li>\n<li>Paketübertragung (<code>loop for Each Packet</code>):</li>\n<li>Sender fragt Nutzdaten über <code>PduR_J1939TpCopyTxData()</code> an. Dabei wird <code>TpDataState = TP_DATACONF</code> für das erste Paket des Blocks bzw. <code>TP_CONFPENDING</code> für Folgepakete gesetzt.</li>\n<li>Sender übermittelt das Datenpaket via <code>TP.DT()</code>.</li>\n<li>Verzweigung Fehlerfall (<code>alt TP.DT lost</code>):</li>\n<li><code>[NO]</code>: Paket kommt fehlerfrei an; Empfänger ruft <code>PduR_J1939TpCopyRxData()</code> auf.</li>\n<li><code>[YES]</code>: Paket geht verloren; Empfänger sendet erneutes <code>TP.CM_CTS()</code> (Anforderung ab Fehlpaket/Blockstart, Notiz: „Next Packet set to first Packet of Block“). Sender fordert über <code>PduR_J1939TpCopyTxData()</code> mit <code>TpDataState = TP_DATARETRY</code> und <code>TxTpDataCnt = Offset in bytes to start of Block</code> erneut Daten ab, sendet <code>TP.DT()</code> erneut und Empfänger reicht die Daten mittels <code>PduR_J1939TpCopyRxData()</code> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Übertragungsabschluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach vollständigem Empfang quittiert <code>:J1939Tp</code> mit <code>TP.EOMACK()</code> an <code>J1939Tp</code> und signalisiert den Abschluss über <code>PduR_J1939TpRxIndication()</code> an <code>:PduR</code>.</li>\n<li>Sender-<code>J1939Tp</code> bestätigt den Gesamtabschluss an <code>PduR</code> mittels <code>PduR_J1939TpTxConfirmation()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt das normative Retry-Verhalten für J1939Tp bei Paketverlust während blockweiser TP.DT-Übertragung. Implementierer müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Der Sender muss bei Retry (<code>TpDataState = TP_DATARETRY</code>) über <code>TxTpDataCnt</code> den Pufferzeiger im oberen Layer (<code>PduR</code>) exakt auf den Byte-Offset des Blockanfangs zurücksetzen können (Pufferverwaltung muss Rückspulen/Rewind unterstützen).</li>\n<li>Der Empfänger detektiert fehlende oder unvollständige Pakete innerhalb eines Blocks und steuert die Wiederholung über ein erneutes CTS mit dem entsprechenden Sequenznummernbezug aus.</li>\n<li>Quittierungszustände (<code>TP_DATACONF</code> vs. <code>TP_CONFPENDING</code>) definieren, ab wann vorherige Blockdaten durch die PDU-Router-Pufferverwaltung freigegeben werden dürfen.</li>\n</ul>"}, {"id": "FIG-9a136db6c6dc2cbb", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform Transportprotokolls nach SAE J1939 (<code>J1939Tp</code>). Das Diagramm illustriert das Zusammenspiel zwischen dem PDU-Router (<code>PduR</code>) und dem <code>J1939Tp</code>-Modul auf Sender- und Empfängerseite während einer verbindungsorientierten Datenübertragung mittels Connection Management (BAM/CM) unter Berücksichtigung von Übertragungsfehlern und Wiederholungsmechanismen (Retry Handling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> instanziiert bzw. adressiert):</p>\n<ul class=\"fig-list\">\n<li><code>PduR</code> (Senderseite, Caller)</li>\n<li><code>J1939Tp</code> (Senderseite, Transport Layer Modul)</li>\n<li><code>:J1939Tp</code> (Empfängerseite, korrespondierender Transport Layer Endpunkt)</li>\n<li><code>:PduR</code> (Empfängerseite, Callee / Data Sink)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li>Steuer- und Daten-APIs zwischen PduR und J1939Tp: <code>J1939Tp_Transmit()</code>, <code>PduR_J1939TpStartOfReception()</code>, <code>PduR_J1939TpCopyTxData()</code>, <code>PduR_J1939TpCopyRxData()</code>, <code>PduR_J1939TpRxIndication()</code>, <code>PduR_J1939TpTxConfirmation()</code></li>\n<li>SAE J1939 Protokollnachrichten (CAN-Bus-Ebene): <code>TP.CM_RTS()</code>, <code>TP.CM_CTS()</code>, <code>TP.DT()</code>, <code>TP.EOMACK()</code></li>\n<li>Zustandsvariablen / interne Parameter: <code>TpDataState</code> (<code>TP_DATACONF</code>, <code>TP_CONFPENDING</code>, <code>TP_DATARETRY</code>), <code>TxTpDataCnt</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Verbindungsaufbau:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> initiiert die Übertragung über <code>J1939Tp_Transmit()</code>.</li>\n<li>Sender-<code>J1939Tp</code> sendet die Verbindungsanforderung <code>TP.CM_RTS()</code> an <code>:J1939Tp</code>.</li>\n<li>Empfänger meldet den Beginn über <code>PduR_J1939TpStartOfReception()</code> an <code>:PduR</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Blockübertragung (<code>loop for Each Block</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger antwortet mit <code>TP.CM_CTS()</code> zur Freigabe eines Übertragungsblocks.</li>\n<li>Paketübertragung (<code>loop for Each Packet</code>):</li>\n<li>Sender fragt Nutzdaten über <code>PduR_J1939TpCopyTxData()</code> an. Dabei wird <code>TpDataState = TP_DATACONF</code> für das erste Paket des Blocks bzw. <code>TP_CONFPENDING</code> für Folgepakete gesetzt.</li>\n<li>Sender übermittelt das Datenpaket via <code>TP.DT()</code>.</li>\n<li>Verzweigung Fehlerfall (<code>alt TP.DT lost</code>):</li>\n<li><code>[NO]</code>: Paket kommt fehlerfrei an; Empfänger ruft <code>PduR_J1939TpCopyRxData()</code> auf.</li>\n<li><code>[YES]</code>: Paket geht verloren; Empfänger sendet erneutes <code>TP.CM_CTS()</code> (Anforderung ab Fehlpaket/Blockstart, Notiz: „Next Packet set to first Packet of Block“). Sender fordert über <code>PduR_J1939TpCopyTxData()</code> mit <code>TpDataState = TP_DATARETRY</code> und <code>TxTpDataCnt = Offset in bytes to start of Block</code> erneut Daten ab, sendet <code>TP.DT()</code> erneut und Empfänger reicht die Daten mittels <code>PduR_J1939TpCopyRxData()</code> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Übertragungsabschluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach vollständigem Empfang quittiert <code>:J1939Tp</code> mit <code>TP.EOMACK()</code> an <code>J1939Tp</code> und signalisiert den Abschluss über <code>PduR_J1939TpRxIndication()</code> an <code>:PduR</code>.</li>\n<li>Sender-<code>J1939Tp</code> bestätigt den Gesamtabschluss an <code>PduR</code> mittels <code>PduR_J1939TpTxConfirmation()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt das normative Retry-Verhalten für J1939Tp bei Paketverlust während blockweiser TP.DT-Übertragung. Implementierer müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Der Sender muss bei Retry (<code>TpDataState = TP_DATARETRY</code>) über <code>TxTpDataCnt</code> den Pufferzeiger im oberen Layer (<code>PduR</code>) exakt auf den Byte-Offset des Blockanfangs zurücksetzen können (Pufferverwaltung muss Rückspulen/Rewind unterstützen).</li>\n<li>Der Empfänger detektiert fehlende oder unvollständige Pakete innerhalb eines Blocks und steuert die Wiederholung über ein erneutes CTS mit dem entsprechenden Sequenznummernbezug aus.</li>\n<li>Quittierungszustände (<code>TP_DATACONF</code> vs. <code>TP_CONFPENDING</code>) definieren, ab wann vorherige Blockdaten durch die PDU-Router-Pufferverwaltung freigegeben werden dürfen.</li>\n</ul>"}, {"id": "FIG-58f0e130ab13c1c7", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform Transportprotokolls nach SAE J1939 (<code>J1939Tp</code>). Das Diagramm illustriert das Zusammenspiel zwischen dem PDU-Router (<code>PduR</code>) und dem <code>J1939Tp</code>-Modul auf Sender- und Empfängerseite während einer verbindungsorientierten Datenübertragung mittels Connection Management (BAM/CM) unter Berücksichtigung von Übertragungsfehlern und Wiederholungsmechanismen (Retry Handling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> instanziiert bzw. adressiert):</p>\n<ul class=\"fig-list\">\n<li><code>PduR</code> (Senderseite, Caller)</li>\n<li><code>J1939Tp</code> (Senderseite, Transport Layer Modul)</li>\n<li><code>:J1939Tp</code> (Empfängerseite, korrespondierender Transport Layer Endpunkt)</li>\n<li><code>:PduR</code> (Empfängerseite, Callee / Data Sink)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li>Steuer- und Daten-APIs zwischen PduR und J1939Tp: <code>J1939Tp_Transmit()</code>, <code>PduR_J1939TpStartOfReception()</code>, <code>PduR_J1939TpCopyTxData()</code>, <code>PduR_J1939TpCopyRxData()</code>, <code>PduR_J1939TpRxIndication()</code>, <code>PduR_J1939TpTxConfirmation()</code></li>\n<li>SAE J1939 Protokollnachrichten (CAN-Bus-Ebene): <code>TP.CM_RTS()</code>, <code>TP.CM_CTS()</code>, <code>TP.DT()</code>, <code>TP.EOMACK()</code></li>\n<li>Zustandsvariablen / interne Parameter: <code>TpDataState</code> (<code>TP_DATACONF</code>, <code>TP_CONFPENDING</code>, <code>TP_DATARETRY</code>), <code>TxTpDataCnt</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Verbindungsaufbau:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> initiiert die Übertragung über <code>J1939Tp_Transmit()</code>.</li>\n<li>Sender-<code>J1939Tp</code> sendet die Verbindungsanforderung <code>TP.CM_RTS()</code> an <code>:J1939Tp</code>.</li>\n<li>Empfänger meldet den Beginn über <code>PduR_J1939TpStartOfReception()</code> an <code>:PduR</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Blockübertragung (<code>loop for Each Block</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger antwortet mit <code>TP.CM_CTS()</code> zur Freigabe eines Übertragungsblocks.</li>\n<li>Paketübertragung (<code>loop for Each Packet</code>):</li>\n<li>Sender fragt Nutzdaten über <code>PduR_J1939TpCopyTxData()</code> an. Dabei wird <code>TpDataState = TP_DATACONF</code> für das erste Paket des Blocks bzw. <code>TP_CONFPENDING</code> für Folgepakete gesetzt.</li>\n<li>Sender übermittelt das Datenpaket via <code>TP.DT()</code>.</li>\n<li>Verzweigung Fehlerfall (<code>alt TP.DT lost</code>):</li>\n<li><code>[NO]</code>: Paket kommt fehlerfrei an; Empfänger ruft <code>PduR_J1939TpCopyRxData()</code> auf.</li>\n<li><code>[YES]</code>: Paket geht verloren; Empfänger sendet erneutes <code>TP.CM_CTS()</code> (Anforderung ab Fehlpaket/Blockstart, Notiz: „Next Packet set to first Packet of Block“). Sender fordert über <code>PduR_J1939TpCopyTxData()</code> mit <code>TpDataState = TP_DATARETRY</code> und <code>TxTpDataCnt = Offset in bytes to start of Block</code> erneut Daten ab, sendet <code>TP.DT()</code> erneut und Empfänger reicht die Daten mittels <code>PduR_J1939TpCopyRxData()</code> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Übertragungsabschluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach vollständigem Empfang quittiert <code>:J1939Tp</code> mit <code>TP.EOMACK()</code> an <code>J1939Tp</code> und signalisiert den Abschluss über <code>PduR_J1939TpRxIndication()</code> an <code>:PduR</code>.</li>\n<li>Sender-<code>J1939Tp</code> bestätigt den Gesamtabschluss an <code>PduR</code> mittels <code>PduR_J1939TpTxConfirmation()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt das normative Retry-Verhalten für J1939Tp bei Paketverlust während blockweiser TP.DT-Übertragung. Implementierer müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Der Sender muss bei Retry (<code>TpDataState = TP_DATARETRY</code>) über <code>TxTpDataCnt</code> den Pufferzeiger im oberen Layer (<code>PduR</code>) exakt auf den Byte-Offset des Blockanfangs zurücksetzen können (Pufferverwaltung muss Rückspulen/Rewind unterstützen).</li>\n<li>Der Empfänger detektiert fehlende oder unvollständige Pakete innerhalb eines Blocks und steuert die Wiederholung über ein erneutes CTS mit dem entsprechenden Sequenznummernbezug aus.</li>\n<li>Quittierungszustände (<code>TP_DATACONF</code> vs. <code>TP_CONFPENDING</code>) definieren, ab wann vorherige Blockdaten durch die PDU-Router-Pufferverwaltung freigegeben werden dürfen.</li>\n</ul>"}, {"id": "FIG-4a19f660e2eedfbc", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform Transportprotokolls nach SAE J1939 (<code>J1939Tp</code>). Das Diagramm illustriert das Zusammenspiel zwischen dem PDU-Router (<code>PduR</code>) und dem <code>J1939Tp</code>-Modul auf Sender- und Empfängerseite während einer verbindungsorientierten Datenübertragung mittels Connection Management (BAM/CM) unter Berücksichtigung von Übertragungsfehlern und Wiederholungsmechanismen (Retry Handling).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> instanziiert bzw. adressiert):</p>\n<ul class=\"fig-list\">\n<li><code>PduR</code> (Senderseite, Caller)</li>\n<li><code>J1939Tp</code> (Senderseite, Transport Layer Modul)</li>\n<li><code>:J1939Tp</code> (Empfängerseite, korrespondierender Transport Layer Endpunkt)</li>\n<li><code>:PduR</code> (Empfängerseite, Callee / Data Sink)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li>Steuer- und Daten-APIs zwischen PduR und J1939Tp: <code>J1939Tp_Transmit()</code>, <code>PduR_J1939TpStartOfReception()</code>, <code>PduR_J1939TpCopyTxData()</code>, <code>PduR_J1939TpCopyRxData()</code>, <code>PduR_J1939TpRxIndication()</code>, <code>PduR_J1939TpTxConfirmation()</code></li>\n<li>SAE J1939 Protokollnachrichten (CAN-Bus-Ebene): <code>TP.CM_RTS()</code>, <code>TP.CM_CTS()</code>, <code>TP.DT()</code>, <code>TP.EOMACK()</code></li>\n<li>Zustandsvariablen / interne Parameter: <code>TpDataState</code> (<code>TP_DATACONF</code>, <code>TP_CONFPENDING</code>, <code>TP_DATARETRY</code>), <code>TxTpDataCnt</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Verbindungsaufbau:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PduR</code> initiiert die Übertragung über <code>J1939Tp_Transmit()</code>.</li>\n<li>Sender-<code>J1939Tp</code> sendet die Verbindungsanforderung <code>TP.CM_RTS()</code> an <code>:J1939Tp</code>.</li>\n<li>Empfänger meldet den Beginn über <code>PduR_J1939TpStartOfReception()</code> an <code>:PduR</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Blockübertragung (<code>loop for Each Block</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger antwortet mit <code>TP.CM_CTS()</code> zur Freigabe eines Übertragungsblocks.</li>\n<li>Paketübertragung (<code>loop for Each Packet</code>):</li>\n<li>Sender fragt Nutzdaten über <code>PduR_J1939TpCopyTxData()</code> an. Dabei wird <code>TpDataState = TP_DATACONF</code> für das erste Paket des Blocks bzw. <code>TP_CONFPENDING</code> für Folgepakete gesetzt.</li>\n<li>Sender übermittelt das Datenpaket via <code>TP.DT()</code>.</li>\n<li>Verzweigung Fehlerfall (<code>alt TP.DT lost</code>):</li>\n<li><code>[NO]</code>: Paket kommt fehlerfrei an; Empfänger ruft <code>PduR_J1939TpCopyRxData()</code> auf.</li>\n<li><code>[YES]</code>: Paket geht verloren; Empfänger sendet erneutes <code>TP.CM_CTS()</code> (Anforderung ab Fehlpaket/Blockstart, Notiz: „Next Packet set to first Packet of Block“). Sender fordert über <code>PduR_J1939TpCopyTxData()</code> mit <code>TpDataState = TP_DATARETRY</code> und <code>TxTpDataCnt = Offset in bytes to start of Block</code> erneut Daten ab, sendet <code>TP.DT()</code> erneut und Empfänger reicht die Daten mittels <code>PduR_J1939TpCopyRxData()</code> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Übertragungsabschluss:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach vollständigem Empfang quittiert <code>:J1939Tp</code> mit <code>TP.EOMACK()</code> an <code>J1939Tp</code> und signalisiert den Abschluss über <code>PduR_J1939TpRxIndication()</code> an <code>:PduR</code>.</li>\n<li>Sender-<code>J1939Tp</code> bestätigt den Gesamtabschluss an <code>PduR</code> mittels <code>PduR_J1939TpTxConfirmation()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt das normative Retry-Verhalten für J1939Tp bei Paketverlust während blockweiser TP.DT-Übertragung. Implementierer müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Der Sender muss bei Retry (<code>TpDataState = TP_DATARETRY</code>) über <code>TxTpDataCnt</code> den Pufferzeiger im oberen Layer (<code>PduR</code>) exakt auf den Byte-Offset des Blockanfangs zurücksetzen können (Pufferverwaltung muss Rückspulen/Rewind unterstützen).</li>\n<li>Der Empfänger detektiert fehlende oder unvollständige Pakete innerhalb eines Blocks und steuert die Wiederholung über ein erneutes CTS mit dem entsprechenden Sequenznummernbezug aus.</li>\n<li>Quittierungszustände (<code>TP_DATACONF</code> vs. <code>TP_CONFPENDING</code>) definieren, ab wann vorherige Blockdaten durch die PDU-Router-Pufferverwaltung freigegeben werden dürfen.</li>\n</ul>"}], "trans": [{"from": "FIG-49f66202298a5bb6", "to": "FIG-d5705d4016da7b3c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d5705d4016da7b3c", "to": "FIG-9a136db6c6dc2cbb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9a136db6c6dc2cbb", "to": "FIG-58f0e130ab13c1c7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-58f0e130ab13c1c7", "to": "FIG-4a19f660e2eedfbc", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
